class ProvenanceVectorTests(unittest.TestCase):
    def test_literal_complete_input_and_roots(self):
        g,named=provenance_graph()
        self.assertEqual(BUNDLE_BYTES,c(g.records))
        self.assertEqual(BUNDLE_SHA256,hashlib.sha256(BUNDLE_BYTES).hexdigest())
        self.assertEqual(9,len(VECTORS))
        for name,root,rootwire,rootsha,manifest,wire,sha in VECTORS:
            with self.subTest(vector=name):
                self.assertEqual(named[name],root)
                self.assertEqual(rootwire,c([root]))
                self.assertEqual(rootsha,hashlib.sha256(rootwire).hexdigest())
                self.assertEqual(manifest,g.closure([root]))
                self.assertEqual(wire,c(manifest))
                self.assertEqual(sha,hashlib.sha256(wire).hexdigest())

    def test_literal_verified_manifests(self):
        g,_=provenance_graph()
        for name,root,rootwire,rootsha,manifest,wire,sha in VECTORS:
            with self.subTest(vector=name):
                actual=verify_si_provenance(g.records,[root])
                self.assertEqual(manifest,actual)
                self.assertEqual(wire,canonical_si_json(actual))
                self.assertEqual(sha,hashlib.sha256(canonical_si_json(actual)).hexdigest())


if __name__=='__main__':unittest.main()
